css:
:where(.wtyg-map-site_wealth_atlas){--bg:#0b0e12; --panel:rgba(11,14,18,.90); --line:#222b35;
    --ink:#eef2f6; --dim:#8e9aa6; --faint:#5d6873;
    --gold:#d8b772; --gold-soft:#caa24f; --plat:#cfdae6; --plat-soft:#9fb0c2;}
:where(.wtyg-map-site_wealth_atlas),:where(.wtyg-map-site_wealth_atlas){margin:0;padding:0;}
:where(.wtyg-map-site_wealth_atlas) *{box-sizing:border-box;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="wrap"],#wtyg-noid-wrap){position:relative;width:100%;height:770px;overflow:hidden;background:var(--bg);
    border:1px solid var(--line);
    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="map"],#wtyg-noid-map){position:absolute;inset:0;}
:where(.wtyg-map-site_wealth_atlas) .sat-dim .leaflet-tile{filter:grayscale(.42) brightness(.60) contrast(1.10) saturate(.80);}
:where(.wtyg-map-site_wealth_atlas) .ui{position:absolute;z-index:1000;background:var(--panel);color:var(--ink);
    border:1px solid var(--line);border-radius:8px;
    backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
    box-shadow:0 10px 30px rgba(0,0,0,.55);}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="title"],#wtyg-noid-title){top:16px;left:16px;max-width:320px;padding:13px 16px;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="title"],#wtyg-noid-title) .ey{font:600 9.5px/1 ui-monospace,Menlo,monospace;letter-spacing:2.4px;
    text-transform:uppercase;color:var(--gold);}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="title"],#wtyg-noid-title) h1{margin:6px 0 4px;font-size:17px;font-weight:650;letter-spacing:-.2px;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="title"],#wtyg-noid-title) p{margin:0;font-size:11px;line-height:1.55;color:var(--dim);}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="controls"],#wtyg-noid-controls){top:16px;right:16px;width:236px;padding:13px 14px;}
:where(.wtyg-map-site_wealth_atlas) .lbl{font:600 8.5px/1 ui-monospace,Menlo,monospace;letter-spacing:1.8px;
    text-transform:uppercase;color:var(--faint);margin:0 0 8px;}
:where(.wtyg-map-site_wealth_atlas) .chips{display:flex;flex-direction:column;gap:6px;margin-bottom:13px;}
:where(.wtyg-map-site_wealth_atlas) .chip{display:flex;align-items:center;gap:9px;border:1px solid var(--line);border-radius:6px;
    padding:7px 10px;cursor:pointer;transition:.15s;font-size:11.5px;color:var(--dim);user-select:none;}
:where(.wtyg-map-site_wealth_atlas) .chip:hover{background:rgba(255,255,255,.04);color:var(--ink);}
:where(.wtyg-map-site_wealth_atlas) .chip.on{border-color:var(--gold);color:var(--ink);background:rgba(216,183,114,.07);}
:where(.wtyg-map-site_wealth_atlas) .chip .sw{width:11px;height:11px;border-radius:50%;flex:0 0 auto;}
:where(.wtyg-map-site_wealth_atlas) .chip .ct{margin-left:auto;font:9px ui-monospace,Menlo,monospace;color:var(--faint);}
:where(.wtyg-map-site_wealth_atlas) .sw-g{background:rgba(202,162,79,.30);border:1.5px solid var(--gold);}
:where(.wtyg-map-site_wealth_atlas) .sw-i{background:rgba(159,176,194,.28);border:1.5px solid var(--plat);}
:where(.wtyg-map-site_wealth_atlas) .sw-u{background:rgba(202,162,79,.05);border:1.5px solid var(--gold);}
:where(.wtyg-map-site_wealth_atlas) select{width:100%;background:#0e131a;color:var(--ink);border:1px solid var(--line);
    border-radius:6px;padding:8px 9px;font:13px inherit;cursor:pointer;
    -webkit-appearance:none;appearance:none;
    background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6'><path d='M0 0l5 6 5-6z' fill='%238e9aa6'/></svg>");
    background-repeat:no-repeat;background-position:right 10px center;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="stat"],#wtyg-noid-stat){margin-top:13px;padding-top:12px;border-top:1px solid var(--line);
    font-size:11px;color:var(--dim);line-height:1.5;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="stat"],#wtyg-noid-stat) .big{font-size:18px;font-weight:700;color:var(--gold);letter-spacing:-.3px;
    display:block;margin:3px 0 1px;font-variant-numeric:tabular-nums;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="info-toggle"],#wtyg-noid-info-toggle){margin-top:11px;font:600 10.5px/1 inherit;color:var(--gold);cursor:pointer;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="info-toggle"],#wtyg-noid-info-toggle):hover{text-decoration:underline;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="about"],#wtyg-noid-about){bottom:16px;right:16px;max-width:320px;padding:14px 16px;display:none;
    font-size:11px;line-height:1.6;color:var(--dim);}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="about"],#wtyg-noid-about).open{display:block;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="about"],#wtyg-noid-about) .h{color:var(--gold);font-weight:600;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="about"],#wtyg-noid-about) strong{color:var(--ink);}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="about"],#wtyg-noid-about) p{margin:0 0 9px;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="about"],#wtyg-noid-about) p:last-child{margin:0;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="legend"],#wtyg-noid-legend){bottom:16px;left:16px;padding:13px 15px;width:228px;}
:where(.wtyg-map-site_wealth_atlas) .lg-row{display:flex;align-items:center;gap:9px;margin:6px 0;font-size:11px;color:var(--dim);}
:where(.wtyg-map-site_wealth_atlas) .lg-mk{width:14px;height:14px;border-radius:50%;flex:0 0 auto;}
:where(.wtyg-map-site_wealth_atlas) .mk-fam{background:rgba(202,162,79,.22);border:1.5px solid var(--gold);}
:where(.wtyg-map-site_wealth_atlas) .mk-ind{background:rgba(159,176,194,.20);border:1.25px solid var(--plat);}
:where(.wtyg-map-site_wealth_atlas) .mk-na{background:transparent;border:1.5px dashed var(--gold);}
:where(.wtyg-map-site_wealth_atlas) .lg-line{width:14px;height:0;border-top:1px solid var(--gold);opacity:.5;flex:0 0 auto;}
:where(.wtyg-map-site_wealth_atlas) .lg-scale{display:flex;align-items:flex-end;gap:13px;margin:11px 0 3px;padding-top:11px;
    border-top:1px solid var(--line);}
:where(.wtyg-map-site_wealth_atlas) .lg-scale .u{display:flex;flex-direction:column;align-items:center;gap:5px;}
:where(.wtyg-map-site_wealth_atlas) .lg-scale svg circle{fill:rgba(216,183,114,.12);stroke:var(--gold);stroke-width:1.25;}
:where(.wtyg-map-site_wealth_atlas) .lg-scale .cap{font:9px ui-monospace,Menlo,monospace;color:var(--faint);}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="legend"],#wtyg-noid-legend) .src{margin-top:10px;padding-top:9px;border-top:1px solid var(--line);
    font:9px/1.55 ui-monospace,Menlo,monospace;color:var(--faint);}
:where(.wtyg-map-site_wealth_atlas) .leaflet-popup-content-wrapper{background:#0b0e12;color:var(--ink);border:1px solid var(--line);
    border-radius:9px;box-shadow:0 12px 34px rgba(0,0,0,.6);}
:where(.wtyg-map-site_wealth_atlas) .leaflet-popup-tip{background:#0b0e12;border:1px solid var(--line);}
:where(.wtyg-map-site_wealth_atlas) .leaflet-popup-content{margin:13px 16px;font-family:inherit;min-width:190px;}
:where(.wtyg-map-site_wealth_atlas) .pp-top{display:flex;justify-content:space-between;align-items:baseline;gap:10px;}
:where(.wtyg-map-site_wealth_atlas) .pp-rank{font:600 9px/1 ui-monospace,Menlo,monospace;letter-spacing:1.3px;color:var(--faint);}
:where(.wtyg-map-site_wealth_atlas) .pp-tier{font:600 8px/1 ui-monospace,Menlo,monospace;letter-spacing:.8px;text-transform:uppercase;}
:where(.wtyg-map-site_wealth_atlas) .pp-tier.fam{color:var(--gold);}
:where(.wtyg-map-site_wealth_atlas) .pp-tier.ind{color:var(--plat);}
:where(.wtyg-map-site_wealth_atlas) .pp-name{font-size:15px;font-weight:680;margin:5px 0 1px;letter-spacing:-.2px;}
:where(.wtyg-map-site_wealth_atlas) .pp-amt{font-size:21px;font-weight:800;letter-spacing:-.5px;margin:4px 0 2px;font-variant-numeric:tabular-nums;}
:where(.wtyg-map-site_wealth_atlas) .pp-amt small{font-size:10px;font-weight:500;color:var(--dim);letter-spacing:0;}
:where(.wtyg-map-site_wealth_atlas) .pp-na{font:11px ui-monospace,Menlo,monospace;color:var(--gold);margin:5px 0;}
:where(.wtyg-map-site_wealth_atlas) .pp-meta{font-size:11px;color:var(--dim);line-height:1.55;margin-top:3px;}
:where(.wtyg-map-site_wealth_atlas) .pp-meta b{color:var(--ink);font-weight:600;}
:where(.wtyg-map-site_wealth_atlas) .leaflet-tooltip.tt{background:#0b0e12;border:1px solid var(--line);color:var(--ink);
    font:600 11px/1 inherit;border-radius:5px;box-shadow:0 6px 18px rgba(0,0,0,.5);}
:where(.wtyg-map-site_wealth_atlas) .leaflet-tooltip.tt:before{display:none;}
:where(.wtyg-map-site_wealth_atlas) .leaflet-tooltip.tt .v{color:var(--gold);font-variant-numeric:tabular-nums;}
:where(.wtyg-map-site_wealth_atlas) .leaflet-control-attribution{font-size:9px;background:rgba(11,14,18,.7)!important;color:var(--faint)!important;}
:where(.wtyg-map-site_wealth_atlas) .leaflet-control-attribution a{color:var(--dim)!important;}
:where(.wtyg-map-site_wealth_atlas) .leaflet-bar a{background:#0e131a;color:var(--ink);border-color:var(--line);}
:where(.wtyg-map-site_wealth_atlas) .leaflet-bar a:hover{background:#172029;}
@media (max-width:620px){:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="title"],#wtyg-noid-title){max-width:52%;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="controls"],#wtyg-noid-controls){width:172px;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="legend"],#wtyg-noid-legend){display:none;}
:where(.wtyg-map-site_wealth_atlas) :is([data-wtyg-id="about"],#wtyg-noid-about){max-width:78%;}}
